mapper.insert:
insert into CHB_LOAN_DETAIL_CONTRACT(PROD_ID, ASSET_CODE, ORIG_CCY, ORIG_CONTRACT_AMOUNT, ORIG_CONTRACT_AMOUNT_CNY, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ORG_CODE, DEPT_CODE, STATUS, DATA_SOURCE) select PROD_ID, ASSET_CODE, ORIG_CCY, ORIG_CONTRACT_AMOUNT, ORIG_CONTRACT_AMOUNT_CNY, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, ORG_CODE, DEPT_CODE, STATUS, DATA_SOURCE from ( select TEMP.* from (
SELECT #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.origCcy,jdbcType=DATE} ORIG_CCY, #{item.origContractAmount,jdbcType=DECIMAL} ORIG_CONTRACT_AMOUNT, #{item.origContractAmountCny,jdbcType=DECIMAL} ORIG_CONTRACT_AMOUNT_CNY, NOW() CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, now() CREATE_TIME, NOW() UPDATE_USER, now() UPDATE_TIME, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE FROM DUAL
) TEMP where not exists (select 1 from CHB_LOAN_DETAIL_CONTRACT CII where CII.PROD_ID = TEMP.PROD_ID and CII.ASSET_CODE = TEMP.ASSET_CODE and CII.ORIG_CCY = TEMP.ORIG_CCY) ) de ;
UPDATE CHB_LOAN_DETAIL_CONTRACT as A, ( select ORIG_CONTRACT_AMOUNT, ORIG_CONTRACT_AMOUNT_CNY, CREATE_USER, CREATE_DEPT, UPDATE_USER, UPDATE_TIME, ORG_CODE, DEPT_CODE, STATUS, DATA_SOURCE from ( select TEMP.* from (
SELECT #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.assetCode,jdbcType=VARCHAR} ASSET_CODE, #{item.origCcy,jdbcType=DATE} ORIG_CCY, #{item.origContractAmount,jdbcType=DECIMAL} ORIG_CONTRACT_AMOUNT, #{item.origContractAmountCny,jdbcType=DECIMAL} ORIG_CONTRACT_AMOUNT_CNY, NOW() CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, now() CREATE_TIME, NOW() UPDATE_USER, now() UPDATE_TIME, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_LOAN_DETAIL_CONTRACT CII where CII.PROD_ID = TEMP.PROD_ID and CII.ASSET_CODE = TEMP.ASSET_CODE and CII.ORIG_CCY = TEMP.ORIG_CCY);

